insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system', 'The human digestive system consists of the gastrointestinal tract plus the accessory organs of digestion (the tongue, salivary glands, pancreas, liver, and gallbladder). Digestion involves the breakdown of food into smaller and smaller components, until they can be absorbed and assimilated into the body. The process of digestion has three stages: the cephalic phase, the gastric phase, and the intestinal phase. The first stage, the cephalic phase of digestion, begins with secretions from gastric glands in response to the sight and smell of food, and continues in the mouth with the mechanical breakdown of food by chewing, and the chemical breakdown by digestive enzymes in the saliva. Saliva contains amylase, and lingual lipase, secreted by the salivary glands, and serous glands on the tongue. Chewing mixes the food with saliva to produce a food bolus to be swallowed down the esophagus to enter the stomach. The second stage, the gastric phase, takes place in the stomach, where the food is further broken down by mixing with gastric juice until it passes into the duodenum, the first part of the small intestine. The intestinal phase where the partially digested food is mixed with pancreatic digestive enzymes completes the process of digestion.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The human digestive system consists of the gastrointestinal tract plus the accessory organs of digestion (the tongue, salivary glands, pancreas, liver, and gallbladder). Digestion involves the breakdown of food into smaller and smaller components, until they can be absorbed and assimilated into the body. The process of digestion has three stages: the cephalic phase, the gastric phase, and the intestinal phase. The first stage, the cephalic phase of digestion, begins with secretions from gastric glands in response to the sight and smell of food, and continues in the mouth with the mechanical breakdown of food by chewing, and the chemical breakdown by digestive enzymes in the saliva. Saliva contains amylase, and lingual lipase, secreted by the salivary glands, and serous glands on the tongue. Chewing mixes the food with saliva to produce a food bolus to be swallowed down the esophagus to enter the stomach. The second stage, the gastric phase, takes place in the stomach, where the food is further broken down by mixing with gastric juice until it passes into the duodenum, the first part of the small intestine. The intestinal phase where the partially digested food is mixed with pancreatic digestive enzymes completes the process of digestion.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system', 'Digestion is helped by the chewing of food carried out by the muscles of mastication, the tongue, and the teeth, and also by the contractions of peristalsis, and segmentation. Gastric juice containing gastric acid, and the production of mucus in the stomach, are essential for the continuation of digestion. Peristalsis is the rhythmic contraction of muscles that begins in the esophagus and continues along the wall of the stomach and the rest of the gastrointestinal tract. This initially results in the production of chyme which when fully broken down in the small intestine is absorbed as chyle into the lymphatic system. Most of the digestion of food takes place in the small intestine. Water and some minerals are reabsorbed back into the blood in the large intestine. The waste products of digestion (feces) are excreted from the rectum via the anus.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Digestion is helped by the chewing of food carried out by the muscles of mastication, the tongue, and the teeth, and also by the contractions of peristalsis, and segmentation. Gastric juice containing gastric acid, and the production of mucus in the stomach, are essential for the continuation of digestion. Peristalsis is the rhythmic contraction of muscles that begins in the esophagus and continues along the wall of the stomach and the rest of the gastrointestinal tract. This initially results in the production of chyme which when fully broken down in the small intestine is absorbed as chyle into the lymphatic system. Most of the digestion of food takes place in the small intestine. Water and some minerals are reabsorbed back into the blood in the large intestine. The waste products of digestion (feces) are excreted from the rectum via the anus.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system: Components', 'There are several organs involved in the digestion of food. The organs that are outside of the gastrointestinal tract (GI tract) but associated with digestion, are known as the accessory digestive organs and include the mouth, and tongue, and glandular organs – the salivary glands, the liver, gall bladder and pancreas. Other components considered are the teeth and epiglottis. A number of sphincters in the GI tract are also involved in digestion, including those of the esophagus (esophageal sphincters) and stomach (pyloric sphincter). The largest structure of the digestive system is the GI tract. This starts at the mouth and ends at the anus, covering a distance of about nine metres (30 ft). A major digestive organ is the stomach. Within its mucosa are millions of embedded gastric glands. Their secretions as gastric juice are vital to the functioning of the organ. Most of the digestion of food takes place in the small intestine, which is responsible for chemical digestion and the absorption of water and nutrients into the bloodstream. It is followed by the large intestine, which further absorbs water and electrolytes from digestive contents, and stores the remaining waste matter (faeces) until it is expelled through defecation. The small intestine is the longest part of the GI tract but has a smaller diameter than the large intestine.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'There are several organs involved in the digestion of food. The organs that are outside of the gastrointestinal tract (GI tract) but associated with digestion, are known as the accessory digestive organs and include the mouth, and tongue, and glandular organs – the salivary glands, the liver, gall bladder and pancreas. Other components considered are the teeth and epiglottis. A number of sphincters in the GI tract are also involved in digestion, including those of the esophagus (esophageal sphincters) and stomach (pyloric sphincter). The largest structure of the digestive system is the GI tract. This starts at the mouth and ends at the anus, covering a distance of about nine metres (30 ft). A major digestive organ is the stomach. Within its mucosa are millions of embedded gastric glands. Their secretions as gastric juice are vital to the functioning of the organ. Most of the digestion of food takes place in the small intestine, which is responsible for chemical digestion and the absorption of water and nutrients into the bloodstream. It is followed by the large intestine, which further absorbs water and electrolytes from digestive contents, and stores the remaining waste matter (faeces) until it is expelled through defecation. The small intestine is the longest part of the GI tract but has a smaller diameter than the large intestine.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system: Components', 'There are many specialised cells of the GI tract. These include the taste receptors, various cells of the gastric glands, centroacinar cells of the pancreas, enterocytes lining the intestinal epithelium, and microfold cells also known as mucosal cells, mainly found in gut-associated lymphoid tissue of the small intestine. Some parts of the digestive system are also part of the excretory system, including the large intestine.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'There are many specialised cells of the GI tract. These include the taste receptors, various cells of the gastric glands, centroacinar cells of the pancreas, enterocytes lining the intestinal epithelium, and microfold cells also known as mucosal cells, mainly found in gut-associated lymphoid tissue of the small intestine. Some parts of the digestive system are also part of the excretory system, including the large intestine.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system: Mouth', 'The mouth is the first part of the upper gastrointestinal tract and is equipped with several structures that begin the first processes of digestion. These include salivary glands, teeth and the tongue. The mouth consists of two regions; the vestibule and the oral cavity proper. The vestibule is the area between the teeth, lips and cheeks, and the rest is the oral cavity proper. Most of the oral cavity is lined with oral mucosa, a mucous membrane that produces a lubricating mucus, of which only a small amount is needed. Mucous membranes vary in structure in the different regions of the body but they all produce a lubricating mucus, which is either secreted by surface cells or more usually by underlying glands. The mucous membrane in the mouth continues as the thin mucosa which lines the bases of the teeth. The main component of mucus is a glycoprotein called mucin and the type secreted varies according to the region involved. Mucin is viscous, clear, and clinging. Underlying the mucous membrane in the mouth is a thin layer of smooth muscle tissue and the loose connection to the membrane gives it its great elasticity. It covers the cheeks, inner surfaces of the lips, and floor of the mouth, and the mucin produced is highly protective against tooth decay.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The mouth is the first part of the upper gastrointestinal tract and is equipped with several structures that begin the first processes of digestion. These include salivary glands, teeth and the tongue. The mouth consists of two regions; the vestibule and the oral cavity proper. The vestibule is the area between the teeth, lips and cheeks, and the rest is the oral cavity proper. Most of the oral cavity is lined with oral mucosa, a mucous membrane that produces a lubricating mucus, of which only a small amount is needed. Mucous membranes vary in structure in the different regions of the body but they all produce a lubricating mucus, which is either secreted by surface cells or more usually by underlying glands. The mucous membrane in the mouth continues as the thin mucosa which lines the bases of the teeth. The main component of mucus is a glycoprotein called mucin and the type secreted varies according to the region involved. Mucin is viscous, clear, and clinging. Underlying the mucous membrane in the mouth is a thin layer of smooth muscle tissue and the loose connection to the membrane gives it its great elasticity. It covers the cheeks, inner surfaces of the lips, and floor of the mouth, and the mucin produced is highly protective against tooth decay.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system: Mouth', 'The roof of the mouth is termed the palate and it separates the oral cavity from the nasal cavity. The palate is hard at the front of the mouth since the overlying mucosa is covering a plate of bone; it is softer and more pliable at the back being made of muscle and connective tissue, and it can move to swallow food and liquids. The soft palate ends at the uvula. The surface of the hard palate allows for the pressure needed in eating food, to leave the nasal passage clear. The opening between the lips is termed the oral fissure, and the opening into the throat is called the fauces. At either side of the soft palate are the palatoglossus muscles which also reach into regions of the tongue. These muscles raise the back of the tongue and also close both sides of the fauces to enable food to be swallowed. Mucus helps in the mastication of food in its ability to soften and collect the food in the formation of the bolus.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The roof of the mouth is termed the palate and it separates the oral cavity from the nasal cavity. The palate is hard at the front of the mouth since the overlying mucosa is covering a plate of bone; it is softer and more pliable at the back being made of muscle and connective tissue, and it can move to swallow food and liquids. The soft palate ends at the uvula. The surface of the hard palate allows for the pressure needed in eating food, to leave the nasal passage clear. The opening between the lips is termed the oral fissure, and the opening into the throat is called the fauces. At either side of the soft palate are the palatoglossus muscles which also reach into regions of the tongue. These muscles raise the back of the tongue and also close both sides of the fauces to enable food to be swallowed. Mucus helps in the mastication of food in its ability to soften and collect the food in the formation of the bolus.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system: Salivary glands', 'There are three pairs of main salivary glands and between 800 and 1,000 minor salivary glands, all of which mainly serve the digestive process, and also play an important role in the maintenance of dental health and general mouth lubrication, without which speech would be impossible. The main glands are all exocrine glands, secreting via ducts. All of these glands terminate in the mouth. The largest of these are the parotid glands—their secretion is mainly serous. The next pair are underneath the jaw, the submandibular glands, these produce both serous fluid and mucus. The serous fluid is produced by serous glands in these salivary glands which also produce lingual lipase. They produce about 70% of the oral cavity saliva. The third pair are the sublingual glands located underneath the tongue and their secretion is mainly mucous with a small percentage of saliva.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'There are three pairs of main salivary glands and between 800 and 1,000 minor salivary glands, all of which mainly serve the digestive process, and also play an important role in the maintenance of dental health and general mouth lubrication, without which speech would be impossible. The main glands are all exocrine glands, secreting via ducts. All of these glands terminate in the mouth. The largest of these are the parotid glands—their secretion is mainly serous. The next pair are underneath the jaw, the submandibular glands, these produce both serous fluid and mucus. The serous fluid is produced by serous glands in these salivary glands which also produce lingual lipase. They produce about 70% of the oral cavity saliva. The third pair are the sublingual glands located underneath the tongue and their secretion is mainly mucous with a small percentage of saliva.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Human digestive system: Salivary glands', 'Within the oral mucosa, and also on the tongue, palates, and floor of the mouth, are the minor salivary glands; their secretions are mainly mucous and they are innervated by the facial nerve (CN7). The glands also secrete amylase a first stage in the breakdown of food acting on the carbohydrate in the food to transform the starch content into maltose. There are other serous glands on the surface of the tongue that encircle taste buds on the back part of the tongue and these also produce lingual lipase. Lipase is a digestive enzyme that catalyses the hydrolysis of lipids (fats). These glands are termed Von Ebner''s glands which have also been shown to have another function in the secretion of histatins which offer an early defense (outside of the immune system) against microbes in food, when it makes contact with these glands on the tongue tissue. Sensory information can stimulate the secretion of saliva providing the necessary fluid for the tongue to work with and also to ease swallowing of the food.', 'Wikipedia: Human digestive system', 'https://en.wikipedia.org/w/index.php?title=Human_digestive_system&oldid=1379840794', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Within the oral mucosa, and also on the tongue, palates, and floor of the mouth, are the minor salivary glands; their secretions are mainly mucous and they are innervated by the facial nerve (CN7). The glands also secrete amylase a first stage in the breakdown of food acting on the carbohydrate in the food to transform the starch content into maltose. There are other serous glands on the surface of the tongue that encircle taste buds on the back part of the tongue and these also produce lingual lipase. Lipase is a digestive enzyme that catalyses the hydrolysis of lipids (fats). These glands are termed Von Ebner''s glands which have also been shown to have another function in the secretion of histatins which offer an early defense (outside of the immune system) against microbes in food, when it makes contact with these glands on the tongue tissue. Sensory information can stimulate the secretion of saliva providing the necessary fluid for the tongue to work with and also to ease swallowing of the food.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine', 'The small intestine or small bowel is an organ in the gastrointestinal tract where most of the absorption of nutrients from food takes place. It lies between the stomach and large intestine, and receives bile and pancreatic juice through the pancreatic duct to aid in digestion. The small intestine is about 6.5 metres (21 feet) long and folds many times to fit in the abdomen. Although it is longer than the large intestine, it is called the small intestine because it is narrower in diameter. The small intestine has three distinct regions – the duodenum, jejunum, and ileum. The duodenum, the shortest, is where preparation for absorption through small finger-like protrusions called intestinal villi begins. The jejunum is specialized for the absorption through its lining by enterocytes of small nutrient particles which have been previously digested by enzymes in the duodenum. The main function of the ileum is to absorb vitamin B12, bile salts, and whatever products of digestion were not absorbed by the jejunum.', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The small intestine or small bowel is an organ in the gastrointestinal tract where most of the absorption of nutrients from food takes place. It lies between the stomach and large intestine, and receives bile and pancreatic juice through the pancreatic duct to aid in digestion. The small intestine is about 6.5 metres (21 feet) long and folds many times to fit in the abdomen. Although it is longer than the large intestine, it is called the small intestine because it is narrower in diameter. The small intestine has three distinct regions – the duodenum, jejunum, and ileum. The duodenum, the shortest, is where preparation for absorption through small finger-like protrusions called intestinal villi begins. The jejunum is specialized for the absorption through its lining by enterocytes of small nutrient particles which have been previously digested by enzymes in the duodenum. The main function of the ileum is to absorb vitamin B12, bile salts, and whatever products of digestion were not absorbed by the jejunum.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine: Size', 'The length of the small intestine can vary greatly, from as short as 3 metres (10 feet) to as long as 10.5 m (34+1⁄2 ft), also depending on the measuring technique used. The typical length in a living person is 3–5 m (10–16+1⁄2 ft). The length depends both on how tall the person is and how the length is measured. Taller people generally have a longer small intestine and measurements are generally longer after death and when the bowel is empty. It is approximately 1.5 centimetres (5⁄8 inch) in diameter in newborns after 35 weeks of gestational age, and 2.5–3 cm (1–1+1⁄8 in) in diameter in adults. On abdominal X-rays, the small intestine is considered to be abnormally dilated when the diameter exceeds 3 cm. On CT scans, a diameter of over 2.5 cm is considered abnormally dilated. The surface area of the human small intestinal mucosa, due to enlargement caused by folds, villi and microvilli, averages 30 square metres (320 sq ft).', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The length of the small intestine can vary greatly, from as short as 3 metres (10 feet) to as long as 10.5 m (34+1⁄2 ft), also depending on the measuring technique used. The typical length in a living person is 3–5 m (10–16+1⁄2 ft). The length depends both on how tall the person is and how the length is measured. Taller people generally have a longer small intestine and measurements are generally longer after death and when the bowel is empty. It is approximately 1.5 centimetres (5⁄8 inch) in diameter in newborns after 35 weeks of gestational age, and 2.5–3 cm (1–1+1⁄8 in) in diameter in adults. On abdominal X-rays, the small intestine is considered to be abnormally dilated when the diameter exceeds 3 cm. On CT scans, a diameter of over 2.5 cm is considered abnormally dilated. The surface area of the human small intestinal mucosa, due to enlargement caused by folds, villi and microvilli, averages 30 square metres (320 sq ft).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine: Parts', 'The duodenum is a short structure ranging from 20–25 cm (8–10 in) in length, and shaped like a "C". It surrounds the head of the pancreas. It receives gastric chyme from the stomach, together with digestive juices from the pancreas (digestive enzymes) and the liver (bile). The digestive enzymes break down proteins and bile emulsifies fats into micelles. The duodenum contains Brunner''s glands, which produce a mucus-rich alkaline secretion containing bicarbonate. These secretions, in combination with bicarbonate from the pancreas, neutralize the stomach acids contained in gastric chyme. The jejunum is the midsection of the small intestine, connecting the duodenum to the ileum. It is about 2.5 m (8 ft) long, and contains the circular folds, and intestinal villi that increase its surface area. Products of digestion (sugars, amino acids, and fatty acids) are absorbed into the bloodstream here. The suspensory muscle of duodenum marks the division between the duodenum and the jejunum. The ileum: The final section of the small intestine. It is about 3 m (9.8 feet) long, and contains villi similar to the jejunum. It absorbs mainly vitamin B12 and bile acids, as well as any other remaining nutrients. The ileum joins to the cecum of the large intestine at the ileocecal junction.', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The duodenum is a short structure ranging from 20–25 cm (8–10 in) in length, and shaped like a "C". It surrounds the head of the pancreas. It receives gastric chyme from the stomach, together with digestive juices from the pancreas (digestive enzymes) and the liver (bile). The digestive enzymes break down proteins and bile emulsifies fats into micelles. The duodenum contains Brunner''s glands, which produce a mucus-rich alkaline secretion containing bicarbonate. These secretions, in combination with bicarbonate from the pancreas, neutralize the stomach acids contained in gastric chyme. The jejunum is the midsection of the small intestine, connecting the duodenum to the ileum. It is about 2.5 m (8 ft) long, and contains the circular folds, and intestinal villi that increase its surface area. Products of digestion (sugars, amino acids, and fatty acids) are absorbed into the bloodstream here. The suspensory muscle of duodenum marks the division between the duodenum and the jejunum. The ileum: The final section of the small intestine. It is about 3 m (9.8 feet) long, and contains villi similar to the jejunum. It absorbs mainly vitamin B12 and bile acids, as well as any other remaining nutrients. The ileum joins to the cecum of the large intestine at the ileocecal junction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine: Parts', 'The jejunum and ileum are suspended in the abdominal cavity by mesentery. The mesentery is part of the peritoneum. Arteries, veins, lymph vessels and nerves travel within the mesentery.', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The jejunum and ileum are suspended in the abdominal cavity by mesentery. The mesentery is part of the peritoneum. Arteries, veins, lymph vessels and nerves travel within the mesentery.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine: Blood supply', 'The small intestine receives a blood supply from the celiac trunk and the superior mesenteric artery. These are both branches of the aorta. The duodenum receives blood from the celiac trunk via the superior pancreaticoduodenal artery and from the superior mesenteric artery via the inferior pancreaticoduodenal artery. These two arteries both have anterior and posterior branches that meet in the midline and anastomose. The jejunum and ileum receive blood from the superior mesenteric artery. Branches of the superior mesenteric artery form a series of arches within the mesentery known as arterial arcades, which may be several layers deep. Straight blood vessels known as vasa recta travel from the arcades closest to the ileum and jejunum to the organs themselves.', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The small intestine receives a blood supply from the celiac trunk and the superior mesenteric artery. These are both branches of the aorta. The duodenum receives blood from the celiac trunk via the superior pancreaticoduodenal artery and from the superior mesenteric artery via the inferior pancreaticoduodenal artery. These two arteries both have anterior and posterior branches that meet in the midline and anastomose. The jejunum and ileum receive blood from the superior mesenteric artery. Branches of the superior mesenteric artery form a series of arches within the mesentery known as arterial arcades, which may be several layers deep. Straight blood vessels known as vasa recta travel from the arcades closest to the ileum and jejunum to the organs themselves.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine: Microanatomy', 'The three sections of the small intestine look similar to each other at a microscopic level, but there are some important differences. The parts of the intestine are as follows:', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The three sections of the small intestine look similar to each other at a microscopic level, but there are some important differences. The parts of the intestine are as follows:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine: Gene and protein expression', 'About 20,000 protein coding genes are expressed in human cells and 70% of these genes are expressed in the normal duodenum. Some 300 of these genes are more specifically expressed in the duodenum with very few genes expressed only in the small intestine. The corresponding specific proteins are expressed in glandular cells of the mucosa, such as fatty acid binding protein FABP6. Most of the more specifically expressed genes in the small intestine are also expressed in the duodenum, for example FABP2 and the DEFA6 protein expressed in secretory granules of Paneth cells.', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'About 20,000 protein coding genes are expressed in human cells and 70% of these genes are expressed in the normal duodenum. Some 300 of these genes are more specifically expressed in the duodenum with very few genes expressed only in the small intestine. The corresponding specific proteins are expressed in glandular cells of the mucosa, such as fatty acid binding protein FABP6. Most of the more specifically expressed genes in the small intestine are also expressed in the duodenum, for example FABP2 and the DEFA6 protein expressed in secretory granules of Paneth cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Small intestine: Development', 'The small intestine develops from the midgut of the primitive gut tube. By the fifth week of embryological life, the ileum begins to grow longer at a very fast rate, forming a U-shaped fold called the primary intestinal loop. The loop grows so fast in length that it outgrows the abdomen and protrudes through the umbilicus. By week 10, the loop retracts back into the abdomen. Between weeks six and ten the small intestine rotates anticlockwise, as viewed from the front of the embryo. It rotates a further 180 degrees after it has moved back into the abdomen. This process creates the twisted shape of the large intestine.', 'Wikipedia: Small intestine', 'https://en.wikipedia.org/w/index.php?title=Small_intestine&oldid=1370380104', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The small intestine develops from the midgut of the primitive gut tube. By the fifth week of embryological life, the ileum begins to grow longer at a very fast rate, forming a U-shaped fold called the primary intestinal loop. The loop grows so fast in length that it outgrows the abdomen and protrudes through the umbilicus. By week 10, the loop retracts back into the abdomen. Between weeks six and ten the small intestine rotates anticlockwise, as viewed from the front of the embryo. It rotates a further 180 degrees after it has moved back into the abdomen. This process creates the twisted shape of the large intestine.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver', 'The liver is a major metabolic organ exclusively found in vertebrates which performs many essential biological functions, such as detoxification of the organism and the synthesis of various proteins and other biochemicals necessary for digestion and growth. In humans, it is located in the right upper quadrant of the abdomen, below the diaphragm and mostly shielded by the lower right rib cage. Its other metabolic roles include carbohydrate metabolism, the production of a number of hormones, conversion and storage of nutrients such as glucose and glycogen, and the decomposition of red blood cells. Anatomical and medical terminology often use the prefix hepat- from ἡπατο-, from the Greek word for liver, such as hepatology, and hepatitis.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The liver is a major metabolic organ exclusively found in vertebrates which performs many essential biological functions, such as detoxification of the organism and the synthesis of various proteins and other biochemicals necessary for digestion and growth. In humans, it is located in the right upper quadrant of the abdomen, below the diaphragm and mostly shielded by the lower right rib cage. Its other metabolic roles include carbohydrate metabolism, the production of a number of hormones, conversion and storage of nutrients such as glucose and glycogen, and the decomposition of red blood cells. Anatomical and medical terminology often use the prefix hepat- from ἡπατο-, from the Greek word for liver, such as hepatology, and hepatitis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver', 'The liver is also an accessory digestive organ that produces bile, an alkaline fluid containing cholesterol and bile acids, which emulsifies and aids the break up of dietary fat. The gallbladder, a small hollow pouch that sits just under the right lobe of liver, stores and concentrates the bile produced by the liver, which is later excreted to the duodenum to help with digestion. The liver''s highly specialized tissue, consisting mostly of hepatocytes, regulates a wide variety of high-volume biochemical reactions, including the synthesis and breakdown of small and complex organic molecules, many of which are necessary for normal vital functions. Estimates regarding the organ''s total number of functions vary, but are generally cited as being around 500. For this reason, the liver has sometimes been described as the body''s chemical factory. It is not known how to compensate for the absence of liver function in the long term, although liver dialysis techniques can be used in the short term. Artificial livers have not been developed to promote long-term replacement in the absence of the liver. As of 2018, liver transplantation is the only option for complete liver failure. The liver is the largest internal organ in vertebrates and its structure is similar in all other vertebrates. It is mostly divided into right and left lobes.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The liver is also an accessory digestive organ that produces bile, an alkaline fluid containing cholesterol and bile acids, which emulsifies and aids the break up of dietary fat. The gallbladder, a small hollow pouch that sits just under the right lobe of liver, stores and concentrates the bile produced by the liver, which is later excreted to the duodenum to help with digestion. The liver''s highly specialized tissue, consisting mostly of hepatocytes, regulates a wide variety of high-volume biochemical reactions, including the synthesis and breakdown of small and complex organic molecules, many of which are necessary for normal vital functions. Estimates regarding the organ''s total number of functions vary, but are generally cited as being around 500. For this reason, the liver has sometimes been described as the body''s chemical factory. It is not known how to compensate for the absence of liver function in the long term, although liver dialysis techniques can be used in the short term. Artificial livers have not been developed to promote long-term replacement in the absence of the liver. As of 2018, liver transplantation is the only option for complete liver failure. The liver is the largest internal organ in vertebrates and its structure is similar in all other vertebrates. It is mostly divided into right and left lobes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver: Structure', 'The liver is a dark reddish brown, wedge-shaped organ with two lobes of unequal size and shape. A human liver normally weighs approximately 1.5 kilograms (3.3 pounds) and has a width of about 15 centimetres (6 inches). There is considerable size variation between individuals, with the standard reference range for men being 970–1,860 grams (2.14–4.10 lb) and for women 600–1,770 g (1.32–3.90 lb). It is both the heaviest internal organ and the largest gland in the human body. It is located in the right upper quadrant of the abdominal cavity, resting just below the diaphragm, to the right of the stomach, and overlying the gallbladder. The liver is connected to two large blood vessels: the hepatic artery and the portal vein. The hepatic artery carries oxygen-rich blood from the aorta via the celiac trunk, whereas the portal vein carries blood rich in digested nutrients from the entire gastrointestinal tract and also from the spleen and pancreas. These blood vessels subdivide into small capillaries known as liver sinusoids, which then lead to hepatic lobules.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The liver is a dark reddish brown, wedge-shaped organ with two lobes of unequal size and shape. A human liver normally weighs approximately 1.5 kilograms (3.3 pounds) and has a width of about 15 centimetres (6 inches). There is considerable size variation between individuals, with the standard reference range for men being 970–1,860 grams (2.14–4.10 lb) and for women 600–1,770 g (1.32–3.90 lb). It is both the heaviest internal organ and the largest gland in the human body. It is located in the right upper quadrant of the abdominal cavity, resting just below the diaphragm, to the right of the stomach, and overlying the gallbladder. The liver is connected to two large blood vessels: the hepatic artery and the portal vein. The hepatic artery carries oxygen-rich blood from the aorta via the celiac trunk, whereas the portal vein carries blood rich in digested nutrients from the entire gastrointestinal tract and also from the spleen and pancreas. These blood vessels subdivide into small capillaries known as liver sinusoids, which then lead to hepatic lobules.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver: Structure', 'Hepatic lobules are the functional units of the liver. Each lobule is made up of millions of hepatocytes, which are the basic metabolic cells. The lobules are held together by a fine, dense, irregular, fibroelastic connective tissue layer extending from the fibrous capsule covering the entire liver known as Glisson''s capsule after British doctor Francis Glisson. This tissue extends into the structure of the liver by accompanying the blood vessels, ducts, and nerves at the hepatic hilum. The whole surface of the liver, except for the bare area, is covered in a serous coat derived from the peritoneum, and this firmly adheres to the inner Glisson''s capsule.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Hepatic lobules are the functional units of the liver. Each lobule is made up of millions of hepatocytes, which are the basic metabolic cells. The lobules are held together by a fine, dense, irregular, fibroelastic connective tissue layer extending from the fibrous capsule covering the entire liver known as Glisson''s capsule after British doctor Francis Glisson. This tissue extends into the structure of the liver by accompanying the blood vessels, ducts, and nerves at the hepatic hilum. The whole surface of the liver, except for the bare area, is covered in a serous coat derived from the peritoneum, and this firmly adheres to the inner Glisson''s capsule.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver: Lobes', 'The liver is grossly divided into two parts when viewed from above – a right and a left lobe – and four parts when viewed from below (left, right, caudate, and quadrate lobes). The falciform ligament makes a superficial division of the liver into a left and right lobe. From below, the two additional lobes are located between the right and left lobes, one in front of the other. A line can be imagined running from the left of the vena cava and all the way forward to divide the liver and gallbladder into two halves. This line is called Cantlie''s line. Other anatomical landmarks include the ligamentum venosum and the round ligament of the liver, which further divide the left side of the liver in two sections. An important anatomical landmark, the porta hepatis, divides this left portion into four segments, which can be numbered starting at the caudate lobe as I in an anticlockwise manner. From this parietal view, seven segments can be seen, because the eighth segment is only visible in the visceral view.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The liver is grossly divided into two parts when viewed from above – a right and a left lobe – and four parts when viewed from below (left, right, caudate, and quadrate lobes). The falciform ligament makes a superficial division of the liver into a left and right lobe. From below, the two additional lobes are located between the right and left lobes, one in front of the other. A line can be imagined running from the left of the vena cava and all the way forward to divide the liver and gallbladder into two halves. This line is called Cantlie''s line. Other anatomical landmarks include the ligamentum venosum and the round ligament of the liver, which further divide the left side of the liver in two sections. An important anatomical landmark, the porta hepatis, divides this left portion into four segments, which can be numbered starting at the caudate lobe as I in an anticlockwise manner. From this parietal view, seven segments can be seen, because the eighth segment is only visible in the visceral view.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver: Surfaces', 'On the diaphragmatic surface, apart from a triangular bare area where it connects to the diaphragm, the liver is covered by a thin, double-layered membrane, the peritoneum, that helps to reduce friction against other organs. This surface covers the convex shape of the two lobes where it accommodates the shape of the diaphragm. The peritoneum folds back on itself to form the falciform ligament and the right and left triangular ligaments. These peritoneal ligaments are not related to the anatomic ligaments in joints, and the right and left triangular ligaments have no known functional importance, though they serve as surface landmarks. The falciform ligament functions to attach the liver to the posterior portion of the anterior body wall. The visceral surface or inferior surface is uneven and concave. It is covered in peritoneum apart from where it attaches the gallbladder and the porta hepatis. The fossa of gallbladder lies to the right of the quadrate lobe, occupied by the gallbladder with its cystic duct close to the right end of porta hepatis.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'On the diaphragmatic surface, apart from a triangular bare area where it connects to the diaphragm, the liver is covered by a thin, double-layered membrane, the peritoneum, that helps to reduce friction against other organs. This surface covers the convex shape of the two lobes where it accommodates the shape of the diaphragm. The peritoneum folds back on itself to form the falciform ligament and the right and left triangular ligaments. These peritoneal ligaments are not related to the anatomic ligaments in joints, and the right and left triangular ligaments have no known functional importance, though they serve as surface landmarks. The falciform ligament functions to attach the liver to the posterior portion of the anterior body wall. The visceral surface or inferior surface is uneven and concave. It is covered in peritoneum apart from where it attaches the gallbladder and the porta hepatis. The fossa of gallbladder lies to the right of the quadrate lobe, occupied by the gallbladder with its cystic duct close to the right end of porta hepatis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver: Impressions', 'Several impressions on the surface of the liver accommodate the various adjacent structures and organs. Underneath the right lobe and to the right of the gallbladder fossa are two impressions, one behind the other and separated by a ridge. The one in front is a shallow colic impression, formed by the hepatic flexure and the one behind is a deeper renal impression accommodating part of the right kidney and part of the suprarenal gland. The suprarenal impression is a small, triangular, depressed area on the liver. It is located close to the right of the fossa, between the bare area and the caudate lobe, and immediately above the renal impression. The greater part of the suprarenal impression is devoid of peritoneum and it lodges the right suprarenal gland. Medial to the renal impression is a third and slightly marked impression, lying between it and the neck of the gall bladder. This is caused by the descending portion of the duodenum, and is known as the duodenal impression.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Several impressions on the surface of the liver accommodate the various adjacent structures and organs. Underneath the right lobe and to the right of the gallbladder fossa are two impressions, one behind the other and separated by a ridge. The one in front is a shallow colic impression, formed by the hepatic flexure and the one behind is a deeper renal impression accommodating part of the right kidney and part of the suprarenal gland. The suprarenal impression is a small, triangular, depressed area on the liver. It is located close to the right of the fossa, between the bare area and the caudate lobe, and immediately above the renal impression. The greater part of the suprarenal impression is devoid of peritoneum and it lodges the right suprarenal gland. Medial to the renal impression is a third and slightly marked impression, lying between it and the neck of the gall bladder. This is caused by the descending portion of the duodenum, and is known as the duodenal impression.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Liver: Impressions', 'The inferior surface of the left lobe of the liver presents behind and to the left of the gastric impression. This is moulded over the upper front surface of the stomach, and to the right of this is a rounded eminence, the tuber omentale, which fits into the concavity of the lesser curvature of the stomach and lies in front of the anterior layer of the lesser omentum.', 'Wikipedia: Liver', 'https://en.wikipedia.org/w/index.php?title=Liver&oldid=1377953370', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The inferior surface of the left lobe of the liver presents behind and to the left of the gastric impression. This is moulded over the upper front surface of the stomach, and to the right of this is a rounded eminence, the tuber omentale, which fits into the concavity of the lesser curvature of the stomach and lies in front of the anterior layer of the lesser omentum.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney', 'In humans, the kidneys are two reddish-brown bean-shaped blood-filtering organs that are a multilobar, multipapillary form of mammalian kidneys, usually without signs of external lobulation. They are located on the left and right in the retroperitoneal space, and in adult humans are about 12 centimetres (4+1⁄2 inches) in length. They receive blood from the paired renal arteries; blood exits into the paired renal veins. Each kidney is attached to a ureter, a tube that carries excreted urine to the bladder. The kidney participates in the control of the volume of various body fluids, fluid osmolality, acid–base balance, various electrolyte concentrations, and removal of toxins. Filtration occurs in the glomerulus: one-fifth of the blood volume that enters the kidneys is filtered. Examples of substances reabsorbed are solute-free water, sodium, bicarbonate, glucose, and amino acids. Examples of substances secreted are hydrogen, ammonium, potassium and uric acid. The nephron is the structural and functional unit of the kidney. Each adult human kidney contains around 1 million nephrons, while a mouse kidney contains only about 12,500 nephrons. The kidneys also carry out functions independent of the nephrons. For example, they convert a precursor of vitamin D to its active form, calcitriol; and synthesize the hormones erythropoietin and renin.', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'In humans, the kidneys are two reddish-brown bean-shaped blood-filtering organs that are a multilobar, multipapillary form of mammalian kidneys, usually without signs of external lobulation. They are located on the left and right in the retroperitoneal space, and in adult humans are about 12 centimetres (4+1⁄2 inches) in length. They receive blood from the paired renal arteries; blood exits into the paired renal veins. Each kidney is attached to a ureter, a tube that carries excreted urine to the bladder. The kidney participates in the control of the volume of various body fluids, fluid osmolality, acid–base balance, various electrolyte concentrations, and removal of toxins. Filtration occurs in the glomerulus: one-fifth of the blood volume that enters the kidneys is filtered. Examples of substances reabsorbed are solute-free water, sodium, bicarbonate, glucose, and amino acids. Examples of substances secreted are hydrogen, ammonium, potassium and uric acid. The nephron is the structural and functional unit of the kidney. Each adult human kidney contains around 1 million nephrons, while a mouse kidney contains only about 12,500 nephrons. The kidneys also carry out functions independent of the nephrons. For example, they convert a precursor of vitamin D to its active form, calcitriol; and synthesize the hormones erythropoietin and renin.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney', 'Chronic kidney disease (CKD) has been recognized as a leading public health problem worldwide. The global estimated prevalence of CKD is 13.4%, and patients with kidney failure needing renal replacement therapy are estimated between 5 and 7 million. Procedures used in the management of kidney disease include chemical and microscopic examination of the urine (urinalysis), measurement of kidney function by calculating the estimated glomerular filtration rate (eGFR) using the serum creatinine; and kidney biopsy and CT scan to evaluate for abnormal anatomy. Dialysis and kidney transplantation are used to treat kidney failure; one (or both sequentially) of these are almost always used when renal function drops below 15%. Nephrectomy is frequently used to cure renal cell carcinoma. Renal physiology is the study of kidney function. Nephrology is the medical specialty that addresses diseases of kidney function: these include CKD, nephritic and nephrotic syndromes, acute kidney injury, and pyelonephritis. Urology addresses diseases of kidney (and urinary tract) anatomy: these include cancer, renal cysts, kidney stones and ureteral stones, and urinary tract obstruction.', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Chronic kidney disease (CKD) has been recognized as a leading public health problem worldwide. The global estimated prevalence of CKD is 13.4%, and patients with kidney failure needing renal replacement therapy are estimated between 5 and 7 million. Procedures used in the management of kidney disease include chemical and microscopic examination of the urine (urinalysis), measurement of kidney function by calculating the estimated glomerular filtration rate (eGFR) using the serum creatinine; and kidney biopsy and CT scan to evaluate for abnormal anatomy. Dialysis and kidney transplantation are used to treat kidney failure; one (or both sequentially) of these are almost always used when renal function drops below 15%. Nephrectomy is frequently used to cure renal cell carcinoma. Renal physiology is the study of kidney function. Nephrology is the medical specialty that addresses diseases of kidney function: these include CKD, nephritic and nephrotic syndromes, acute kidney injury, and pyelonephritis. Urology addresses diseases of kidney (and urinary tract) anatomy: these include cancer, renal cysts, kidney stones and ureteral stones, and urinary tract obstruction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney', 'The word "renal" is an adjective meaning "relating to the kidneys", and its roots are French or late Latin. Whereas according to some opinions, "renal" should be replaced with "kidney" in scientific writings such as "kidney artery", other experts have advocated preserving the use of "renal" as appropriate including in "renal artery".', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The word "renal" is an adjective meaning "relating to the kidneys", and its roots are French or late Latin. Whereas according to some opinions, "renal" should be replaced with "kidney" in scientific writings such as "kidney artery", other experts have advocated preserving the use of "renal" as appropriate including in "renal artery".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney: Structure', 'In humans, the kidneys are located high in the abdominal cavity, one on each side of the spine, and lie in a retroperitoneal position at a slightly oblique angle. The asymmetry within the abdominal cavity, caused by the position of the liver, typically results in the right kidney being slightly lower and smaller than the left, and being placed slightly more to the middle than the left kidney. The left kidney is approximately at the vertebral level T12 to L3, and the right is slightly lower. The right kidney sits just below the diaphragm and posterior to the liver. The left kidney sits below the diaphragm and posterior to the spleen. On top of each kidney is an adrenal gland. The upper parts of the kidneys are partially protected by the 11th and 12th ribs. Each kidney, with its adrenal gland is surrounded by two layers of fat: the perirenal fat present between renal fascia and renal capsule and pararenal fat superior to the renal fascia.', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'In humans, the kidneys are located high in the abdominal cavity, one on each side of the spine, and lie in a retroperitoneal position at a slightly oblique angle. The asymmetry within the abdominal cavity, caused by the position of the liver, typically results in the right kidney being slightly lower and smaller than the left, and being placed slightly more to the middle than the left kidney. The left kidney is approximately at the vertebral level T12 to L3, and the right is slightly lower. The right kidney sits just below the diaphragm and posterior to the liver. The left kidney sits below the diaphragm and posterior to the spleen. On top of each kidney is an adrenal gland. The upper parts of the kidneys are partially protected by the 11th and 12th ribs. Each kidney, with its adrenal gland is surrounded by two layers of fat: the perirenal fat present between renal fascia and renal capsule and pararenal fat superior to the renal fascia.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney: Structure', 'The human kidney is a bean-shaped structure with a convex and a concave border. A recessed area on the concave border is the renal hilum, where the renal artery enters the kidney and the renal vein and ureter leave. The kidney is surrounded by tough fibrous tissue, the renal capsule, which is itself surrounded by perirenal fat, renal fascia, and pararenal fat. The anterior (front) surface of these tissues is the peritoneum, while the posterior (rear) surface is the transversalis fascia. The superior pole of the right kidney is adjacent to the liver. For the left kidney, it is next to the spleen. Both, therefore, move down upon inhalation. A Danish study measured the median renal length to be 11.2 cm (4+7⁄16 in) on the left side and 10.9 cm (4+5⁄16 in) on the right side in adults. Median renal volumes were 146 cm3 (8+15⁄16 cu in) on the left and 134 cm3 (8+3⁄16 cu in) on the right.', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The human kidney is a bean-shaped structure with a convex and a concave border. A recessed area on the concave border is the renal hilum, where the renal artery enters the kidney and the renal vein and ureter leave. The kidney is surrounded by tough fibrous tissue, the renal capsule, which is itself surrounded by perirenal fat, renal fascia, and pararenal fat. The anterior (front) surface of these tissues is the peritoneum, while the posterior (rear) surface is the transversalis fascia. The superior pole of the right kidney is adjacent to the liver. For the left kidney, it is next to the spleen. Both, therefore, move down upon inhalation. A Danish study measured the median renal length to be 11.2 cm (4+7⁄16 in) on the left side and 10.9 cm (4+5⁄16 in) on the right side in adults. Median renal volumes were 146 cm3 (8+15⁄16 cu in) on the left and 134 cm3 (8+3⁄16 cu in) on the right.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney: Gross anatomy', 'The functional substance, or parenchyma, of the human kidney is divided into two major structures: the outer renal cortex and the inner renal medulla. Grossly, these structures take the shape of eight to 18 cone-shaped renal lobes, each containing renal cortex surrounding a portion of medulla called a renal pyramid. Between the renal pyramids are projections of cortex called renal columns. The tip, or papilla, of each pyramid empties urine into a minor calyx; minor calyces empty into major calyces, and major calyces empty into the renal pelvis. This becomes the ureter. At the hilum, the ureter and renal vein exit the kidney and the renal artery enters. Hilar fat and lymphatic tissue with lymph nodes surround these structures. The hilar fat is contiguous with a fat-filled cavity called the renal sinus. The renal sinus collectively contains the renal pelvis and calyces and separates these structures from the renal medullary tissue.', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The functional substance, or parenchyma, of the human kidney is divided into two major structures: the outer renal cortex and the inner renal medulla. Grossly, these structures take the shape of eight to 18 cone-shaped renal lobes, each containing renal cortex surrounding a portion of medulla called a renal pyramid. Between the renal pyramids are projections of cortex called renal columns. The tip, or papilla, of each pyramid empties urine into a minor calyx; minor calyces empty into major calyces, and major calyces empty into the renal pelvis. This becomes the ureter. At the hilum, the ureter and renal vein exit the kidney and the renal artery enters. Hilar fat and lymphatic tissue with lymph nodes surround these structures. The hilar fat is contiguous with a fat-filled cavity called the renal sinus. The renal sinus collectively contains the renal pelvis and calyces and separates these structures from the renal medullary tissue.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney: Blood supply', 'The kidneys receive blood from the renal arteries, left and right, which branch directly from the abdominal aorta. The kidneys receive approximately 20–25% of cardiac output in adult humans. Each renal artery branches into segmental arteries, dividing further into interlobar arteries, which penetrate the renal capsule and extend through the renal columns between the renal pyramids. The interlobar arteries then supply blood to the arcuate arteries that run through the boundary of the cortex and the medulla. Each arcuate artery supplies several interlobular arteries that feed into the afferent arterioles that supply the glomeruli. Blood drains from the kidneys, ultimately into the inferior vena cava. After filtration occurs, the blood moves through a small network of small veins (venules) that converge into interlobular veins. As with the arteriole distribution, the veins follow the same pattern: the interlobular provide blood to the arcuate veins then back to the interlobar veins, which come to form the renal veins which exit the kidney.', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The kidneys receive blood from the renal arteries, left and right, which branch directly from the abdominal aorta. The kidneys receive approximately 20–25% of cardiac output in adult humans. Each renal artery branches into segmental arteries, dividing further into interlobar arteries, which penetrate the renal capsule and extend through the renal columns between the renal pyramids. The interlobar arteries then supply blood to the arcuate arteries that run through the boundary of the cortex and the medulla. Each arcuate artery supplies several interlobular arteries that feed into the afferent arterioles that supply the glomeruli. Blood drains from the kidneys, ultimately into the inferior vena cava. After filtration occurs, the blood moves through a small network of small veins (venules) that converge into interlobular veins. As with the arteriole distribution, the veins follow the same pattern: the interlobular provide blood to the arcuate veins then back to the interlobar veins, which come to form the renal veins which exit the kidney.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Kidney: Nerve supply', 'The kidney and nervous system communicate via the renal plexus, whose fibers course along the renal arteries to reach each kidney. Input from the sympathetic nervous system triggers vasoconstriction in the kidney, thereby reducing renal blood flow. The kidney also receives input from the parasympathetic nervous system, by way of the renal branches of the vagus nerve; the function of this is yet unclear. Sensory input from the kidney travels to the T10–11 levels of the spinal cord and is sensed in the corresponding dermatome. Thus, pain in the flank region may be referred from corresponding kidney.', 'Wikipedia: Kidney', 'https://en.wikipedia.org/w/index.php?title=Kidney&oldid=1379119843', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The kidney and nervous system communicate via the renal plexus, whose fibers course along the renal arteries to reach each kidney. Input from the sympathetic nervous system triggers vasoconstriction in the kidney, thereby reducing renal blood flow. The kidney also receives input from the parasympathetic nervous system, by way of the renal branches of the vagus nerve; the function of this is yet unclear. Sensory input from the kidney travels to the T10–11 levels of the spinal cord and is sensed in the corresponding dermatome. Thus, pain in the flank region may be referred from corresponding kidney.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron', 'The nephron is the minute or microscopic structural and functional unit of the kidney. It is composed of a renal corpuscle and a renal tubule. The renal corpuscle consists of a tuft of capillaries called a glomerulus and a cup-shaped structure called Bowman''s capsule. The renal tubule extends from the capsule. The capsule and tubule are connected and are composed of epithelial cells with a lumen. A healthy adult has 1 to 1.5 million nephrons in each kidney. Blood is filtered as it passes through three layers: the endothelial cells of the capillary wall, its basement membrane, and between the podocyte foot processes of the lining of the capsule. The tubule has adjacent peritubular capillaries that run between the descending and ascending portions of the tubule. As the fluid from the capsule flows down into the tubule, it is processed by the epithelial cells lining the tubule: water is reabsorbed and substances are exchanged (some are added, others are removed); first with the interstitial fluid outside the tubules, and then into the plasma in the adjacent peritubular capillaries through the endothelial cells lining that capillary. This process regulates the volume of body fluid as well as levels of many body substances. At the end of the tubule, the remaining fluid—urine—exits: it is composed of water, metabolic waste, and toxins.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The nephron is the minute or microscopic structural and functional unit of the kidney. It is composed of a renal corpuscle and a renal tubule. The renal corpuscle consists of a tuft of capillaries called a glomerulus and a cup-shaped structure called Bowman''s capsule. The renal tubule extends from the capsule. The capsule and tubule are connected and are composed of epithelial cells with a lumen. A healthy adult has 1 to 1.5 million nephrons in each kidney. Blood is filtered as it passes through three layers: the endothelial cells of the capillary wall, its basement membrane, and between the podocyte foot processes of the lining of the capsule. The tubule has adjacent peritubular capillaries that run between the descending and ascending portions of the tubule. As the fluid from the capsule flows down into the tubule, it is processed by the epithelial cells lining the tubule: water is reabsorbed and substances are exchanged (some are added, others are removed); first with the interstitial fluid outside the tubules, and then into the plasma in the adjacent peritubular capillaries through the endothelial cells lining that capillary. This process regulates the volume of body fluid as well as levels of many body substances. At the end of the tubule, the remaining fluid—urine—exits: it is composed of water, metabolic waste, and toxins.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron', 'The interior of Bowman''s capsule, called Bowman''s space, collects the filtrate from the filtering capillaries of the glomerular tuft, which also contains mesangial cells supporting these capillaries. These components function as the filtration unit and make up the renal corpuscle. The filtering structure (glomerular filtration barrier) has three layers composed of endothelial cells, a basement membrane, and podocyte foot processes. The tubule has five anatomically and functionally different parts: the proximal tubule, which has a convoluted section called the proximal convoluted tubule followed by a straight section (proximal straight tubule); the loop of Henle, which has two parts, the descending loop of Henle ("descending loop") and the ascending loop of Henle ("ascending loop"); the distal convoluted tubule ("distal loop"); the connecting tubule, and the last part of nephron the collecting ducts. Nephrons have two lengths with different urine-concentrating capacities: long juxtamedullary nephrons and short cortical nephrons.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The interior of Bowman''s capsule, called Bowman''s space, collects the filtrate from the filtering capillaries of the glomerular tuft, which also contains mesangial cells supporting these capillaries. These components function as the filtration unit and make up the renal corpuscle. The filtering structure (glomerular filtration barrier) has three layers composed of endothelial cells, a basement membrane, and podocyte foot processes. The tubule has five anatomically and functionally different parts: the proximal tubule, which has a convoluted section called the proximal convoluted tubule followed by a straight section (proximal straight tubule); the loop of Henle, which has two parts, the descending loop of Henle ("descending loop") and the ascending loop of Henle ("ascending loop"); the distal convoluted tubule ("distal loop"); the connecting tubule, and the last part of nephron the collecting ducts. Nephrons have two lengths with different urine-concentrating capacities: long juxtamedullary nephrons and short cortical nephrons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron', 'The four mechanisms used to create and process the filtrate (the result of which is to convert blood to urine) are filtration, reabsorption, secretion and excretion. Filtration or ultrafiltration occurs in the glomerulus and is largely passive: it is dependent on the intracapillary blood pressure. About one-fifth of the plasma is filtered as the blood passes through the glomerular capillaries; four-fifths continues into the peritubular capillaries. Normally the only components of the blood that are not filtered into Bowman''s capsule are blood proteins, red blood cells, white blood cells and platelets. Over 150 liters of fluid enter the glomeruli of an adult every day: 99% of the water in that filtrate is reabsorbed. Reabsorption occurs in the renal tubules and is either passive, due to diffusion, or active, due to pumping against a concentration gradient. Secretion also occurs in the tubules and collecting duct and is active. Substances reabsorbed include: water, sodium chloride, glucose, amino acids, lactate, magnesium, calcium phosphate, uric acid, and bicarbonate. Substances secreted include urea, creatinine, potassium, hydrogen, and uric acid. Some of the hormones which signal the tubules to alter the reabsorption or secretion rate, and thereby maintain homeostasis, include (along with the substance affected) antidiuretic hormone (water), aldosterone (sodium, potassium), parathyroid hormone (calcium, phosphate), atrial natriuretic peptide (sodium) and brain natriuretic peptide (sodium). A countercurrent system in the renal medulla provides the mechanism for generating a hypertonic interstitium, which allows the recovery of solute-free water from within the nephron and returning it to the venous vasculature when appropriate.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The four mechanisms used to create and process the filtrate (the result of which is to convert blood to urine) are filtration, reabsorption, secretion and excretion. Filtration or ultrafiltration occurs in the glomerulus and is largely passive: it is dependent on the intracapillary blood pressure. About one-fifth of the plasma is filtered as the blood passes through the glomerular capillaries; four-fifths continues into the peritubular capillaries. Normally the only components of the blood that are not filtered into Bowman''s capsule are blood proteins, red blood cells, white blood cells and platelets. Over 150 liters of fluid enter the glomeruli of an adult every day: 99% of the water in that filtrate is reabsorbed. Reabsorption occurs in the renal tubules and is either passive, due to diffusion, or active, due to pumping against a concentration gradient. Secretion also occurs in the tubules and collecting duct and is active. Substances reabsorbed include: water, sodium chloride, glucose, amino acids, lactate, magnesium, calcium phosphate, uric acid, and bicarbonate. Substances secreted include urea, creatinine, potassium, hydrogen, and uric acid. Some of the hormones which signal the tubules to alter the reabsorption or secretion rate, and thereby maintain homeostasis, include (along with the substance affected) antidiuretic hormone (water), aldosterone (sodium, potassium), parathyroid hormone (calcium, phosphate), atrial natriuretic peptide (sodium) and brain natriuretic peptide (sodium). A countercurrent system in the renal medulla provides the mechanism for generating a hypertonic interstitium, which allows the recovery of solute-free water from within the nephron and returning it to the venous vasculature when appropriate.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron', 'Some diseases of the nephron predominantly affect either the glomeruli or the tubules. Glomerular diseases include diabetic nephropathy, glomerulonephritis and IgA nephropathy; renal tubular diseases include acute tubular necrosis and polycystic kidney disease.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Some diseases of the nephron predominantly affect either the glomeruli or the tubules. Glomerular diseases include diabetic nephropathy, glomerulonephritis and IgA nephropathy; renal tubular diseases include acute tubular necrosis and polycystic kidney disease.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron: Structure', 'The nephron is the functional unit of the kidney. This means that each separate nephron is where the main work of the kidney is performed.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The nephron is the functional unit of the kidney. This means that each separate nephron is where the main work of the kidney is performed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron: Renal corpuscle', 'The renal corpuscle is the site of the filtration of blood plasma. The renal corpuscle consists of the glomerulus, and the glomerular capsule or Bowman''s capsule. The renal corpuscle has two poles: a vascular pole and a tubular pole. The arterioles from the renal circulation enter and leave the glomerulus at the vascular pole. The glomerular filtrate leaves the Bowman''s capsule at the renal tubule at the urinary pole.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The renal corpuscle is the site of the filtration of blood plasma. The renal corpuscle consists of the glomerulus, and the glomerular capsule or Bowman''s capsule. The renal corpuscle has two poles: a vascular pole and a tubular pole. The arterioles from the renal circulation enter and leave the glomerulus at the vascular pole. The glomerular filtrate leaves the Bowman''s capsule at the renal tubule at the urinary pole.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron: Glomerulus', 'The glomerulus is the network, known as a tuft, of filtering capillaries located at the vascular pole of the renal corpuscle in Bowman''s capsule. Each glomerulus receives its blood supply from an afferent arteriole of the renal circulation. The glomerular blood pressure provides the driving force for water and solutes to be filtered out of the blood plasma, and into the interior of Bowman''s capsule, called Bowman''s space. Only about a fifth of the plasma is filtered in the glomerulus. The rest passes into an efferent arteriole. The diameter of the efferent arteriole is smaller than that of the afferent, and this difference increases the hydrostatic pressure in the glomerulus.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The glomerulus is the network, known as a tuft, of filtering capillaries located at the vascular pole of the renal corpuscle in Bowman''s capsule. Each glomerulus receives its blood supply from an afferent arteriole of the renal circulation. The glomerular blood pressure provides the driving force for water and solutes to be filtered out of the blood plasma, and into the interior of Bowman''s capsule, called Bowman''s space. Only about a fifth of the plasma is filtered in the glomerulus. The rest passes into an efferent arteriole. The diameter of the efferent arteriole is smaller than that of the afferent, and this difference increases the hydrostatic pressure in the glomerulus.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Nephron: Bowman''s capsule', 'The Bowman''s capsule, also called the glomerular capsule, surrounds the glomerulus. It is composed of a visceral inner layer formed by specialized cells called podocytes, and a parietal outer layer composed of simple squamous epithelium. Fluids from blood in the glomerulus are ultrafiltered through several layers, resulting in what is known as the filtrate. The filtrate next moves to the renal tubule, where it is further processed to form urine. The different stages of this fluid are collectively known as the tubular fluid.', 'Wikipedia: Nephron', 'https://en.wikipedia.org/w/index.php?title=Nephron&oldid=1326916017', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The Bowman''s capsule, also called the glomerular capsule, surrounds the glomerulus. It is composed of a visceral inner layer formed by specialized cells called podocytes, and a parietal outer layer composed of simple squamous epithelium. Fluids from blood in the glomerulus are ultrafiltered through several layers, resulting in what is known as the filtrate. The filtrate next moves to the renal tubule, where it is further processed to form urine. The different stages of this fluid are collectively known as the tubular fluid.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin', 'Mammalian vasopressin, also called antidiuretic hormone (ADH), arginine vasopressin (AVP) or argipressin, is a hormone synthesized from the AVP gene as a peptide prohormone in neurons in the hypothalamus, and is converted to AVP. It then travels down the axon terminating in the posterior pituitary, and is released from vesicles into the circulation in response to extracellular fluid hypertonicity (hyperosmolality). AVP has two primary functions. First, it increases the amount of solute-free water reabsorbed back into the circulation from the filtrate in the kidney tubules of the nephrons. Second, AVP constricts arterioles, which increases peripheral vascular resistance and raises arterial blood pressure. A third function is possible. Some AVP may be released directly into the brain from the hypothalamus, and may play an important role in social behavior, sexual motivation and pair bonding, and maternal responses to stress. Vasopressin induces differentiation of stem cells into cardiomyocytes and promotes heart muscle homeostasis.', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Mammalian vasopressin, also called antidiuretic hormone (ADH), arginine vasopressin (AVP) or argipressin, is a hormone synthesized from the AVP gene as a peptide prohormone in neurons in the hypothalamus, and is converted to AVP. It then travels down the axon terminating in the posterior pituitary, and is released from vesicles into the circulation in response to extracellular fluid hypertonicity (hyperosmolality). AVP has two primary functions. First, it increases the amount of solute-free water reabsorbed back into the circulation from the filtrate in the kidney tubules of the nephrons. Second, AVP constricts arterioles, which increases peripheral vascular resistance and raises arterial blood pressure. A third function is possible. Some AVP may be released directly into the brain from the hypothalamus, and may play an important role in social behavior, sexual motivation and pair bonding, and maternal responses to stress. Vasopressin induces differentiation of stem cells into cardiomyocytes and promotes heart muscle homeostasis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin: Function', 'Vasopressin regulates the tonicity of body fluids. It is released from the posterior pituitary in response to hypertonicity and causes the kidneys to reabsorb solute-free water and return it to the circulation from the tubules of the nephron, thus returning the tonicity of the body fluids toward normal. An incidental consequence of this renal reabsorption of water is concentrated urine and reduced urine volume. AVP released in high concentrations may also raise blood pressure by inducing moderate vasoconstriction. AVP also may have a variety of neurological effects on the brain. It may influence pair-bonding in voles. The high-density distributions of vasopressin receptor AVPr1a in prairie vole ventral forebrain regions have been shown to facilitate and coordinate reward circuits during partner preference formation, critical for pair bond formation. A very similar substance, lysine vasopressin (LVP) or lypressin, has the same function in pigs and its synthetic version was used in human AVP deficiency, although it has been largely replaced by desmopressin.', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Vasopressin regulates the tonicity of body fluids. It is released from the posterior pituitary in response to hypertonicity and causes the kidneys to reabsorb solute-free water and return it to the circulation from the tubules of the nephron, thus returning the tonicity of the body fluids toward normal. An incidental consequence of this renal reabsorption of water is concentrated urine and reduced urine volume. AVP released in high concentrations may also raise blood pressure by inducing moderate vasoconstriction. AVP also may have a variety of neurological effects on the brain. It may influence pair-bonding in voles. The high-density distributions of vasopressin receptor AVPr1a in prairie vole ventral forebrain regions have been shown to facilitate and coordinate reward circuits during partner preference formation, critical for pair bond formation. A very similar substance, lysine vasopressin (LVP) or lypressin, has the same function in pigs and its synthetic version was used in human AVP deficiency, although it has been largely replaced by desmopressin.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin: Kidney', 'Increasing the water permeability of cortical collecting tubules (CCT), as well as outer and inner medullary collecting duct (OMCD & IMCD) in the kidney, thus allowing water reabsorption and excretion of more concentrated urine, i.e., antidiuresis. This occurs through increased transcription and insertion of water channels (Aquaporin-2) into the apical membrane of collecting tubule and collecting duct epithelial cells. Aquaporins allow water to move down their osmotic gradient and out of the nephron, increasing the amount of water re-absorbed from the filtrate (forming urine) back into the bloodstream. This effect is mediated by V2 receptors. Vasopressin also increases the concentration of calcium in the collecting duct cells, by episodic release from intracellular stores. Vasopressin, acting through cAMP, also increases transcription of the aquaporin-2 gene, thus increasing the total number of aquaporin-2 molecules in collecting duct cells. Increasing permeability of the inner medullary portion of the collecting duct to urea by regulating the cell surface expression of urea transporters, which facilitates its reabsorption into the medullary interstitium as it travels down the concentration gradient created by removing water from the connecting tubule, cortical collecting duct, and outer medullary collecting duct. Acute increase of sodium absorption across the ascending loop of Henle. This adds to the countercurrent multiplication which aids in proper water reabsorption later in the distal tubule and collecting duct.', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Increasing the water permeability of cortical collecting tubules (CCT), as well as outer and inner medullary collecting duct (OMCD & IMCD) in the kidney, thus allowing water reabsorption and excretion of more concentrated urine, i.e., antidiuresis. This occurs through increased transcription and insertion of water channels (Aquaporin-2) into the apical membrane of collecting tubule and collecting duct epithelial cells. Aquaporins allow water to move down their osmotic gradient and out of the nephron, increasing the amount of water re-absorbed from the filtrate (forming urine) back into the bloodstream. This effect is mediated by V2 receptors. Vasopressin also increases the concentration of calcium in the collecting duct cells, by episodic release from intracellular stores. Vasopressin, acting through cAMP, also increases transcription of the aquaporin-2 gene, thus increasing the total number of aquaporin-2 molecules in collecting duct cells. Increasing permeability of the inner medullary portion of the collecting duct to urea by regulating the cell surface expression of urea transporters, which facilitates its reabsorption into the medullary interstitium as it travels down the concentration gradient created by removing water from the connecting tubule, cortical collecting duct, and outer medullary collecting duct. Acute increase of sodium absorption across the ascending loop of Henle. This adds to the countercurrent multiplication which aids in proper water reabsorption later in the distal tubule and collecting duct.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin: Kidney', 'The hormone vasopressin also stimulates the activity of NKCC2. Vasopressin stimulates sodium chloride reabsorption in the thick ascending limb of the nephron by activating signaling pathways. Vasopressin increases the traffic of NKCC2 to the membrane and phosphorylates some serine and threonine sites on the cytoplasmic N-terminal of the NKCC2 located in the membrane, increasing its activity. Increased NKCC2 activity aids in water reabsorption in the collecting duct through aquaporin 2 channels by creating a hypo-osmotic filtrate.', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The hormone vasopressin also stimulates the activity of NKCC2. Vasopressin stimulates sodium chloride reabsorption in the thick ascending limb of the nephron by activating signaling pathways. Vasopressin increases the traffic of NKCC2 to the membrane and phosphorylates some serine and threonine sites on the cytoplasmic N-terminal of the NKCC2 located in the membrane, increasing its activity. Increased NKCC2 activity aids in water reabsorption in the collecting duct through aquaporin 2 channels by creating a hypo-osmotic filtrate.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin: Central nervous system', 'Vasopressin is released into the brain in a circadian rhythm by neurons of the suprachiasmatic nucleus. Recent evidence suggests that vasopressin may have analgesic effects. The analgesia effects of vasopressin were found to be dependent on both stress and sex.', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Vasopressin is released into the brain in a circadian rhythm by neurons of the suprachiasmatic nucleus. Recent evidence suggests that vasopressin may have analgesic effects. The analgesia effects of vasopressin were found to be dependent on both stress and sex.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin: Gene regulation', 'Vasopressin is regulated by AVP gene expression which is managed by major clock controlled genes. In this circadian circuit known as the transcription-translation feedback loop (TTFL), Per2 protein accumulates and is phosphorylated by CK1E. Per2 subsequently inhibits the transcription factors Clock and BMAL1 in order to reduce Per2 protein levels in the cell. At the same time, Per2 also inhibits the transcription factors for the AVP gene in order to regulate its expression, the expression of vasopressin, and other AVP gene products. Ethanol (alcohol) reduces the calcium-dependent secretion of AVP by blocking voltage-gated calcium channels in neurohypophyseal nerve terminals in rats. Angiotensin II stimulates AVP secretion, in keeping with its general pressor and pro-volumic effects on the body. Atrial natriuretic peptide inhibits AVP secretion, in part by inhibiting Angiotensin II-induced stimulation of AVP secretion.', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'Vasopressin is regulated by AVP gene expression which is managed by major clock controlled genes. In this circadian circuit known as the transcription-translation feedback loop (TTFL), Per2 protein accumulates and is phosphorylated by CK1E. Per2 subsequently inhibits the transcription factors Clock and BMAL1 in order to reduce Per2 protein levels in the cell. At the same time, Per2 also inhibits the transcription factors for the AVP gene in order to regulate its expression, the expression of vasopressin, and other AVP gene products. Ethanol (alcohol) reduces the calcium-dependent secretion of AVP by blocking voltage-gated calcium channels in neurohypophyseal nerve terminals in rats. Angiotensin II stimulates AVP secretion, in keeping with its general pressor and pro-volumic effects on the body. Atrial natriuretic peptide inhibits AVP secretion, in part by inhibiting Angiotensin II-induced stimulation of AVP secretion.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin: Production and secretion', 'The physiological stimulus for secretion of vasopressin is increased osmolality of the plasma, monitored by the hypothalamus. A decreased arterial blood volume, (such as can occur in cirrhosis, nephrosis, and heart failure), stimulates secretion, even in the face of decreased osmolality of the plasma: it supersedes osmolality, but with a milder effect. In other words, the unloading of arterial baroreceptors when the arterial blood volume is low stimulates vasopressin secretion despite the presence of hypoosmolality (hyponatremia). The AVP that is measured in peripheral blood is almost all derived from secretion from the posterior pituitary gland (except in cases of AVP-secreting tumours). Vasopressin is produced by magnocellular neurosecretory neurons in the paraventricular nucleus of hypothalamus (PVN) and supraoptic nucleus (SON). It then travels down the axon through the infundibulum within neurosecretory granules that are found within Herring bodies, localized swellings of the axons and nerve terminals. These carry the peptide directly to the posterior pituitary gland, where it is stored until released into the blood.', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'The physiological stimulus for secretion of vasopressin is increased osmolality of the plasma, monitored by the hypothalamus. A decreased arterial blood volume, (such as can occur in cirrhosis, nephrosis, and heart failure), stimulates secretion, even in the face of decreased osmolality of the plasma: it supersedes osmolality, but with a milder effect. In other words, the unloading of arterial baroreceptors when the arterial blood volume is low stimulates vasopressin secretion despite the presence of hypoosmolality (hyponatremia). The AVP that is measured in peripheral blood is almost all derived from secretion from the posterior pituitary gland (except in cases of AVP-secreting tumours). Vasopressin is produced by magnocellular neurosecretory neurons in the paraventricular nucleus of hypothalamus (PVN) and supraoptic nucleus (SON). It then travels down the axon through the infundibulum within neurosecretory granules that are found within Herring bodies, localized swellings of the axons and nerve terminals. These carry the peptide directly to the posterior pituitary gland, where it is stored until released into the blood.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'digestive-renal', 'Vasopressin: Production and secretion', 'There are other sources of AVP, beyond the hypothalamic magnocellular neurons. For example, AVP is also synthesized by parvocellular neurosecretory neurons of the PVN, transported and released at the median eminence, from which it travels through the hypophyseal portal system to the anterior pituitary, where it stimulates corticotropic cells synergistically with CRH to produce ACTH (by itself it is a weak secretagogue).', 'Wikipedia: Vasopressin', 'https://en.wikipedia.org/w/index.php?title=Vasopressin&oldid=1379401158', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'digestive-renal' and body = 'There are other sources of AVP, beyond the hypothalamic magnocellular neurons. For example, AVP is also synthesized by parvocellular neurosecretory neurons of the PVN, transported and released at the median eminence, from which it travels through the hypophyseal portal system to the anterior pituitary, where it stimulates corticotropic cells synergistically with CRH to produce ACTH (by itself it is a weak secretagogue).');
